const cfg = {
  testModus: false,
  mailAn: 'EMPFAENGER_EINTRAGEN',
  mailVon: 'ABSENDER_EINTRAGEN',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'isc-urkunden',
  iscNewsBotUrl: 'http://isc-news-bot.isc-news-bot.svc.cluster.local:8080',
  wochentag: 4,
  startAb: '17:25',
  endeBis: '20:00'
};
if (!cfg.mailAn.includes('@') || !cfg.mailVon.includes('@')) {
  throw new Error('mailAn und mailVon im Node Konfiguration eintragen');
}
const teile = Object.fromEntries(
  new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/Berlin',
    weekday: 'short',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23'
  }).formatToParts(new Date()).map((p) => [p.type, p.value])
);
const tage = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
const heute = `${teile.year}-${teile.month}-${teile.day}`;
const zeit = `${teile.hour}:${teile.minute}`;
const imFenster = tage[teile.weekday] === cfg.wochentag && zeit >= cfg.startAb && zeit <= cfg.endeBis;
if (!cfg.testModus && !imFenster) return [];
return [{ json: { ...cfg, heute, zeit, jahr: teile.year } }];

const cfg = $('Konfiguration').first().json;
const antwort = $input.first().json || {};
if (antwort.ok !== true || !Array.isArray(antwort.urkunden)) {
  const text = 'Fehler ' + (antwort.errorCode || '-') + ' im Schritt ' + (antwort.step || '-') + ' | ' + (antwort.error || 'keine Antwort vom ISC-News-Bot');
  return [{ json: { art: 'fehler', text } }];
}
const urkunden = antwort.urkunden;
if (cfg.testModus) {
  return urkunden.length > 0 ? [{ json: { art: 'mail', urkunden } }] : [];
}
const speicher = $getWorkflowStaticData('global');
const stand = speicher.urkundenStand;
if (!stand || stand.datum !== cfg.heute) {
  speicher.urkundenStand = { datum: cfg.heute, ids: urkunden.map((u) => u.uid) };
  return [];
}
const bekannt = new Set(stand.ids);
const neue = urkunden.filter((u) => !bekannt.has(u.uid));
if (neue.length === 0) return [];
speicher.urkundenStand = { datum: cfg.heute, ids: [...bekannt, ...neue.map((u) => u.uid)] };
return [{ json: { art: 'mail', urkunden: neue } }];

const cfg = $('Konfiguration').first().json;
const urkunden = $input.first().json.urkunden;
const de = (iso) => (/^\d{4}-\d{2}-\d{2}$/.test(iso || '') ? `${iso.slice(8, 10)}.${iso.slice(5, 7)}.${iso.slice(0, 4)}` : '-');
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const name = (u) => u.name || [u.vorname, u.nachname].filter(Boolean).join(' ') || '-';
const zeilen = (u) => [
  ['Name', name(u)],
  ['Geburtsdatum', de(u.geburtsdatum)],
  ['Abzeichen', u.abzeichen || '-'],
  ['Prüfer', `${u.prueferName || '-'} (${u.prueferNummer || '-'})`],
  ['Registriernummer', u.registriernummer || '-']
];
const text = urkunden.map((u) => zeilen(u).map(([k, v]) => `${k}: ${v}`).join('\n')).join('\n\n');
const html = urkunden
  .map((u) => '<table style="border-collapse:collapse;margin-bottom:16px">' + zeilen(u).map(([k, v]) => `<tr><td style="padding:2px 12px 2px 0"><b>${esc(k)}</b></td><td>${esc(v)}</td></tr>`).join('') + '</table>')
  .join('');
const betreff = (cfg.testModus ? '[TEST] ' : '') + (urkunden.length === 1
  ? `Neue Urkunde: ${urkunden[0].abzeichen || '-'} – ${name(urkunden[0])}`
  : `${urkunden.length} neue Urkunden im ISC`);
return [{ json: { mailAn: cfg.mailAn, mailVon: cfg.mailVon, betreff, text, html } }];
